import {getClient,unwrap} from '../supabase-client.js';import {invoke} from './runtime-service.js';
export const jarvisService={async list(){return unwrap((await getClient()).from('jarvis_jobs').select('id,job_type,scheduled_at,status,source_note_id,last_error').order('scheduled_at',{ascending:false}));},async analyze(noteId){return invoke('jarvis',{noteId});},async confirm(proposalId,runAt){return unwrap((await getClient()).rpc('confirm_jarvis',{proposal_id:proposalId,run_at:runAt}));},async cancel(id){return unwrap((await getClient()).from('jarvis_jobs').update({status:'cancelled'}).eq('id',id).in('status',['draft','scheduled','retry','processing']).select().single());}};
